const { readExportFile } = require('./files');
const { resolveImportFiles } = require('./import-files');
const { createNoopLogger, createResult } = require('./import-support');

async function importObjects(store, importPath, options = {}, deps = {}) {
  const logger = deps.logger || createNoopLogger();
  const { filesToImport, exportDir } = await resolveImportFiles(importPath, {
    ...deps,
    logger
  });
  const results = [];
  const warnings = [];
  const errors = [];

  if (filesToImport.length === 0) {
    const warning = 'No valid export files found to import';
    logger.warn('Import', warning);
    return { success: true, results, warnings: [warning], errors };
  }

  for (const filepath of filesToImport) {
    try {
      const exportData = await readExportFile(filepath, deps);
      logger.info(
        'Import',
        `Importing ${exportData.count} ${exportData.objectType} from ${exportData.storeName}...`
      );

      if (options.dryRun) {
        logger.info('Import', `[DRY RUN] Would import ${exportData.count} ${exportData.objectType}`);
        results.push(
          createResult(exportData.objectType, {
            filepath,
            dryRun: true,
            status: 'success'
          })
        );
        continue;
      }

      const importResult = await deps.importObjectType(
        store,
        exportData,
        { ...options, exportDir, filepath },
        { ...deps, logger }
      );
      results.push(importResult);
    } catch (error) {
      logger.error('Import', `Failed to import from ${filepath}: ${error.message}`);
      errors.push(`${filepath}: ${error.message}`);
      results.push({
        filepath,
        objectType: null,
        status: 'failed',
        created: 0,
        updated: 0,
        skipped: 0,
        errors: 1,
        error: error.message
      });
    }
  }

  return {
    success: errors.length === 0 && results.every((result) => result.status !== 'failed'),
    results,
    warnings,
    errors
  };
}

module.exports = {
  importObjects
};
